export type Options = {
  input: string;
  output: string;
  dryRun: boolean;
};

export function parseArgs(argv: string[]) {
  const options: Options = { input: "", output: "", dryRun: false };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--input") {
      options.input = argv[i + 1];
      i += 1;
    } else if (arg === "--output") {
      options.output = argv[i + 1];
      i += 1;
    } else if (arg === "--dry-run") {
      options.dryRun = true;
    }
  }
  return options;
}

export function usage() {
  return [
    "Usage: tool --input <path> --output <path> [--dry-run]",
    "",
    "Options:",
    "  --input    Input file path.",
    "  --output   Output file path.",
    "  --dry-run  Validate only without writing output."
  ].join("\n");
}
